import sys
from lxml import etree
W="{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
t=etree.parse(sys.argv[1])
body=t.getroot().find(W+"body")
out=[]
def runtext(r):
    s=""
    for e in r.iter():
        if e.tag in (W+"t",W+"delText"): s+=e.text or ""
        elif e.tag==W+"tab": s+="\t"
        elif e.tag==W+"br": s+="\n"
    return s
def para(p):
    s=""
    for ch in p:
        if ch.tag==W+"r": s+=runtext(ch)
        elif ch.tag==W+"ins":
            x="".join(runtext(r) for r in ch.iter(W+"r"))
            if x.strip(): s+="[+"+x+"+]"
            else: s+=x
        elif ch.tag==W+"del":
            x="".join(runtext(r) for r in ch.iter(W+"r"))
            if x.strip(): s+="[-"+x+"-]"
        elif ch.tag==W+"hyperlink": s+="".join(runtext(r) for r in ch.iter(W+"r"))
    return s
for el in body:
    if el.tag==W+"p":
        out.append(para(el))
    elif el.tag==W+"tbl":
        for tr in el.iter(W+"tr"):
            cells=[]
            for tc in tr.iter(W+"tc"):
                cells.append(" / ".join(para(p) for p in tc.iter(W+"p")))
            out.append("| "+" | ".join(cells)+" |")
print("\n".join(l for l in out if l.strip()))
EOF
